select
admins.*
from admins admins

    and admins.id = #{id}
    and admins.name like concat('%',#{name},'%')
    and admins.username = #{username}
    and admins.password = #{password}
    and admins.head_img = #{headImg}
    and admins.create_time = #{createTime}


    limit #{current},#{pageSize}

